const e={cbot455:{guizeshouce:"Rules Manual",jianguanzhiyan:"Regulatory Guidelines",guanyuwomen:"About Us",tiyanhuihuang:"EXPERIENCE THE BRILLIANCE OF",huangjinqihuo:"Gold Futures",quantianhoujiayi:"Trade around the clock in markets that don't sleep",fengxianjiyubingcun:"WHERE RISK MEETS OPPORTUNITY.",zhaodaochanpin:"Find the right Gold futures product for you",tansuochanpin:"Explore our Gold products to find your ideal fit in the world's most active gold derivatives markets, used by individuals and institutions around the globe and traded 23 hours a day.",zuigao24h:"24h High",zuidi24h:"24h Low",chengjiaoliang24h:"24h Volume",tianjiazixuan:"+ WATCHLIST",yichuzixuan:"- WATCHLIST",lijijiaoyi:"TRADE NOW",jiesuojihui:"Unlock a world of opportunities",jiarudingjianjiaoyizhe:"Join the ranks of top traders who have already discovered the power of futures. By creating a CMEGroup.com account, you'll gain access to premium educational resources, market analysis and cutting-edge tools, all at no cost.",kaishijiayi:"START TRADING",chuangjianzhanghu:"CREATE YOUR ACCOUNT",shijiahuangjin:"Test-drive Gold futures",shijiahuangjinmiaoshu:"Enhance your gold trading skills and discover new opportunities with real market data in our risk-free Trading Simulator.",kaishilianxi:"START PRACTICING",texingyoushi:"Features and benefits",lingxianliudongxing:"Leading liquidity",lingxianliudongxingmiaoshu:"With over 200,000 contracts traded on average per day and peaks in OI exceeding 900,000, enter/exit positions with ease.",linghuozhixing:"Flexible trade execution",linghuozhixingmiaoshu:"Access liquidity via central limit order book, block trades, or RFQ.",anquanbaozhang:"Safety and security",anquanbaozhangmiaoshu:"Mitigate counterparty credit risk in a centrally cleared, CFTC-regulated marketplace.",geyefangwen:"Overnight electronic access",geyefangwenmiaoshu:"Manage positions during EMEA and APAC business hours as market-moving global news & events unfold.",qihuoganggan:"Futures leverage",qihuogangganmiaoshu:"Control a larger notional value for a relatively small amount of money, enhancing your buying power.",jiarutiaozhang:"Turn curiosity into confidence: Join a Challenge",lijizhuce:"REGISTER NOW",wuyulunbijiaoyiliang:"Unparalleled daily volumes mean industry-leading liquidity",zhaodaoliudongxing:"Find the liquidity to execute the trading strategies you want—when you want—at the most efficient price. Global benchmark products in every major asset class mean you can act quickly to capture opportunities or minimize risk in the markets you trade.",lianxiwomen:"Contact Us",yazhouzongbu:"Asia Headquarters",cmejituan:"CBOT Group",dianhua:"Phone",youxiang:"Email",richengjiaoliang:"Daily Volume and Open Interest",zuihougengxin:"Last updated",suoyoushuju:"All figures in millions.",jiaoyiriqi:"TRADE DATE",zongji:"TOTAL",cmeglobex:"CBOT GLOBEX",cmeclearport:"CBOT CLEARPORT",gongkaihanjia:"OPEN OUTCRY",chicang:"OPEN INTEREST",richengjiao:"Daily Volume",chicangliang:"Open Interest",mran_biaoti:"Current Market Regulation Advisory Notices (MRANs)",mran_jianjie:"Since the formation of CME Group as a result of the merger of CME and CBOT in 2007, and then the merger with NYMEX/COMEX in 2008, the Market Regulation Department has issued a series of Market Regulation Advisory Notices (MRANs) to the marketplace to provide guidance on the rules. Current MRANs appear below, grouped by the exchange(s) to which they are applicable.",mran_lianxi:"For questions regarding any of the MRANs listed below, please contact the Market Regulation Department via email at {email}.",mran_huoqv:"To obtain a copy of previously issued MRANs or other CME Group advisory notices, please use the Advisory Notice Search.",cme_intro:"As the world’s leading derivatives marketplace, CME Group is where the world comes to manage risk. We enable clients to trade futures, options, cash and OTC markets, optimize portfolios, and analyze data – empowering market participants worldwide to efficiently manage risk and capture opportunities. CME Group exchanges offer the widest range of global benchmark products across all major asset classes based on interest rates, equity indexes, foreign exchange, energy, agricultural products and metals. We meet uncertainty and volatility with confidence and clarity, across the trading lifecycle and around the world.",cme_motto:"Act, trade, grow, invest.",cme_description:"Amid global forces that shift and shake, CME Group offers innovative products and datasets across every major asset class globally, to help individuals and institutions elevate their trading strategy. Learn more in this video.",exchange_rules_title:"Exchange-Specific Rules for CME, CBOT, NYMEX, and COMEX",exchange_rules_description:"CME, CBOT, NYMEX, and COMEX are independent Exchanges, each of which remains a separate, CFTC registered Designated Contract Market with self-regulatory responsibilities and maintains its own set of rules. To provide a common regulatory framework for market users, the rulebooks have been substantially harmonized, making the rules parallel in structure, numbering, and language where possible.",cme_footer_desc:"CME Group is the world's leading derivatives marketplace. The Group operates four Designated Contract Markets (DCMs): CME, CBOT, NYMEX, and COMEX."}};export{e as default};
